  "PSA-127": {
    "bookId": "PSA",
    "bookName": "Psalms",
    "chapterNumber": 127,
    "title": "Psalm 127: Unless Yahweh Builds the House (Restful Sleep)",
    "subtitle": "Stops anxious overwork: “He gives sleep to his loved ones” while welcoming children as bright heritage.",
    "summaryHook": "Stops anxious overwork: “He gives sleep to his loved ones” while welcoming children as bright heritage.",
    "bigPictureText": "Replaces frantic striving with peaceful dependence on God’s blessing.",
    "illustrationTheme": "ill-psa-127",
    "illustrationId": "ill-psa-127",
    "verses": [
      {
        "id": "PSA-127:1",
        "bookId": "PSA",
        "bookName": "Psalms",
        "chapterNumber": 127,
        "verseNumber": 1,
        "text": "Unless Yahweh builds the house, they who build it labor in vain. Unless Yahweh watches over the city, the watchman guards it in vain.",
        "translation": "WEB",
        "illustrationId": "ill-psa-127",
        "linkedEntities": [
          {
            "spanText": "Yahweh",
            "entityId": "term-yahweh"
          }
        ]
      },
      {
        "id": "PSA-127:2",
        "bookId": "PSA",
        "bookName": "Psalms",
        "chapterNumber": 127,
        "verseNumber": 2,
        "text": "It is vain for you to rise up early, to stay up late, eating the bread of toil, for he gives sleep to his loved ones.",
        "translation": "WEB",
        "illustrationId": "ill-psa-127",
        "linkedEntities": []
      },
      {
        "id": "PSA-127:3",
        "bookId": "PSA",
        "bookName": "Psalms",
        "chapterNumber": 127,
        "verseNumber": 3,
        "text": "Behold, children are a heritage of Yahweh. The fruit of the womb is his reward.",
        "translation": "WEB",
        "illustrationId": "ill-psa-127",
        "linkedEntities": [
          {
            "spanText": "Yahweh",
            "entityId": "term-yahweh"
          }
        ]
      },
      {
        "id": "PSA-127:4",
        "bookId": "PSA",
        "bookName": "Psalms",
        "chapterNumber": 127,
        "verseNumber": 4,
        "text": "As arrows in the hand of a mighty man, so are the children of youth.",
        "translation": "WEB",
        "illustrationId": "ill-psa-127",
        "linkedEntities": []
      },
      {
        "id": "PSA-127:5",
        "bookId": "PSA",
        "bookName": "Psalms",
        "chapterNumber": 127,
        "verseNumber": 5,
        "text": "Happy is the man who has his quiver full of them. They won’t be disappointed when they speak with their enemies in the gate.",
        "translation": "WEB",
        "illustrationId": "ill-psa-127",
        "linkedEntities": []
      }
    ]
  },
