        "bookId": "PSA",
        "bookName": "Psalms",
        "chapterNumber": 135,
        "verseNumber": 6,
        "text": "Whatever Yahweh pleased, that he has done, in heaven and in earth, in the seas and in all deeps.",
        "translation": "WEB",
        "illustrationId": "ill-psa-135",
        "linkedEntities": [
          {
            "spanText": "Yahweh",
            "entityId": "term-yahweh"
          }
        ]
